func (s *BagState) WriteDiff(writer *diff.Writer) {
	if diff.HasDirty(s.dirty[bagStateDirtyCapacityWord], bagStateDirtyCapacityMask) {
		writer.Int32(1, s.value.Capacity)
	}
	if diff.HasDirty(s.dirty[bagStateDirtyItemsWord], bagStateDirtyItemsMask) {
		for index := range s.itemsChanges.changes {
			change := &s.itemsChanges.changes[index]
			switch change.operation {
			case diff.OperationClear:
				writer.Clear(2)
			case diff.OperationMapPut:
				data, err := proto.Marshal(s.value.Items[change.key])
				if err != nil {
					panic(err)
				}
				writer.MapPut(2, func(writer *diff.Writer) {
					writer.AppendUint64(change.key)
				}, func(writer *diff.Writer) {
					writer.AppendBytes(data)
				})
			case diff.OperationMapDelete:
				writer.MapDelete(2, func(writer *diff.Writer) {
					writer.AppendUint64(change.key)
				})
			case diff.OperationMapPatch:
				writer.MapPatch(2, func(writer *diff.Writer) {
					writer.AppendUint64(change.key)
				}, func(writer *diff.Writer) {
					if diff.HasDirty(change.dirty[0], 1) {
						writer.Uint64(1, s.value.Items[change.key].Id)
					}
					if diff.HasDirty(change.dirty[0], 2) {
						writer.Int32(2, s.value.Items[change.key].Count)
					}
					if diff.HasDirty(change.dirty[0], 4) {
						writer.Int32(3, s.value.Items[change.key].Level)
					}
				})
			}
		}
	}
	if diff.HasDirty(s.dirty[bagStateDirtyOrderWord], bagStateDirtyOrderMask) {
		for _, change := range s.orderChanges.changes {
			switch change.operation {
			case diff.OperationClear:
				writer.Clear(3)
			case diff.OperationListAppend:
				writer.ListAppend(3, func(writer *diff.Writer) {
					writer.AppendUint64(change.value)
				})
			case diff.OperationListInsert:
				writer.ListInsert(3, change.index, func(writer *diff.Writer) {
					writer.AppendUint64(change.value)
				})
			case diff.OperationListSet:
				writer.ListSet(3, change.index, func(writer *diff.Writer) {
					writer.AppendUint64(change.value)
				})
			case diff.OperationListDelete:
				writer.ListDelete(3, change.index)
			case diff.OperationListMove:
				writer.ListMove(3, change.index, change.to)
			}
		}
	}
	if diff.HasDirty(s.dirty[bagStateDirtySlotsWord], bagStateDirtySlotsMask) {
		for _, change := range s.slotsChanges.changes {
			switch change.operation {
			case diff.OperationClear:
				writer.Clear(4)
			case diff.OperationListAppend:
				writer.ListAppend(4, func(writer *diff.Writer) {
					data, err := proto.Marshal(change.value)
					if err != nil {
						panic(err)
					}
					writer.AppendBytes(data)
				})
			case diff.OperationListInsert:
				writer.ListInsert(4, change.index, func(writer *diff.Writer) {
					data, err := proto.Marshal(change.value)
					if err != nil {
						panic(err)
					}
					writer.AppendBytes(data)
				})
			case diff.OperationListSet:
				writer.ListSet(4, change.index, func(writer *diff.Writer) {
					data, err := proto.Marshal(change.value)
					if err != nil {
						panic(err)
					}
					writer.AppendBytes(data)
				})
			case diff.OperationListDelete:
				writer.ListDelete(4, change.index)
			case diff.OperationListMove:
				writer.ListMove(4, change.index, change.to)
			case diff.OperationListPatch:
				writer.ListPatch(4, change.index, func(writer *diff.Writer) {
					if diff.HasDirty(change.dirty[0], 1) {
						writer.Uint64(1, change.value.Id)
					}
					if diff.HasDirty(change.dirty[0], 2) {
						writer.Int32(2, change.value.Count)
					}
					if diff.HasDirty(change.dirty[0], 4) {
						writer.Int32(3, change.value.Level)
					}
				})
			}
		}
	}
	if diff.HasDirty(s.dirty[bagStateDirtyBlobsWord], bagStateDirtyBlobsMask) {
		for _, change := range s.blobsChanges.changes {
			switch change.operation {
			case diff.OperationClear:
				writer.Clear(5)
			case diff.OperationListAppend:
				writer.ListAppend(5, func(writer *diff.Writer) {
					writer.AppendBytes(change.value)
				})
			case diff.OperationListInsert:
				writer.ListInsert(5, change.index, func(writer *diff.Writer) {
					writer.AppendBytes(change.value)
				})
			case diff.OperationListSet:
				writer.ListSet(5, change.index, func(writer *diff.Writer) {
					writer.AppendBytes(change.value)
				})
			case diff.OperationListDelete:
				writer.ListDelete(5, change.index)
			case diff.OperationListMove:
				writer.ListMove(5, change.index, change.to)
			}
		}
	}
	if diff.HasDirty(s.dirty[bagStateDirtyCountersWord], bagStateDirtyCountersMask) {
		for index := range s.countersChanges.changes {
			change := &s.countersChanges.changes[index]
			switch change.operation {
			case diff.OperationClear:
				writer.Clear(6)
			case diff.OperationMapPut:
				writer.MapPut(6, func(writer *diff.Writer) {
					writer.AppendString(change.key)
				}, func(writer *diff.Writer) {
					writer.AppendInt32(s.value.Counters[change.key])
				})
			case diff.OperationMapDelete:
				writer.MapDelete(6, func(writer *diff.Writer) {
					writer.AppendString(change.key)
				})
			}
		}
	}
}

func ApplyBagDiff(value *Bag, data []byte) error {
	reader := diff.NewReader(data)
	for {
		fieldNumber, operation, payload, ok, err := reader.Next()
		if err != nil || !ok {
			return err
		}
		switch fieldNumber {
		case 1:
			if operation != diff.OperationSetVarint {
				return diff.ErrInvalidData
			}
			value.Capacity = diff.DecodeInt32(payload)
		case 2:
			if operation == diff.OperationClear {
				if len(payload) != 0 {
					return diff.ErrInvalidData
				}
				value.Items = nil
				break
			}
			valueReader := diff.NewValueReader(payload)
			key := valueReader.Uint64()
			switch operation {
			case diff.OperationMapPut:
				itemData := valueReader.Bytes()
				item := &Item{}
				if err := proto.Unmarshal(itemData, item); err != nil {
					return err
				}
				if valueReader.Err() != nil || !valueReader.Done() {
					return diff.ErrInvalidData
				}
				if value.Items == nil {
					value.Items = make(map[uint64]*Item)
				}
				value.Items[key] = item
			case diff.OperationMapDelete:
				if valueReader.Err() != nil || !valueReader.Done() {
					return diff.ErrInvalidData
				}
				delete(value.Items, key)
			case diff.OperationMapPatch:
				patch := valueReader.Remaining()
				if valueReader.Err() != nil {
					return diff.ErrInvalidData
				}
				item := value.Items[key]
				if item == nil {
					item = &Item{}
					if value.Items == nil {
						value.Items = make(map[uint64]*Item)
					}
					value.Items[key] = item
				}
				if err := ApplyItemDiff(item, patch); err != nil {
					return err
				}
			default:
				return diff.ErrInvalidData
			}
		case 3:
			valueReader := diff.NewValueReader(payload)
			switch operation {
			case diff.OperationClear:
				value.Order = nil
			case diff.OperationListAppend:
				item := valueReader.Uint64()
				value.Order = append(value.Order, item)
			case diff.OperationListInsert:
				index := int(valueReader.Uint32())
				item := valueReader.Uint64()
				var zero uint64
				value.Order = append(value.Order, zero)
				copy(value.Order[index+1:], value.Order[index:len(value.Order)-1])
				value.Order[index] = item
			case diff.OperationListSet:
				index := int(valueReader.Uint32())
				item := valueReader.Uint64()
				value.Order[index] = item
			case diff.OperationListDelete:
				index := int(valueReader.Uint32())
				copy(value.Order[index:], value.Order[index+1:])
				value.Order = value.Order[:len(value.Order)-1]
			case diff.OperationListMove:
				from := int(valueReader.Uint32())
				to := int(valueReader.Uint32())
				item := value.Order[from]
				if from < to {
					copy(value.Order[from:to], value.Order[from+1:to+1])
				} else {
					copy(value.Order[to+1:from+1], value.Order[to:from])
				}
				value.Order[to] = item
			default:
				return diff.ErrInvalidData
			}
			if valueReader.Err() != nil || !valueReader.Done() {
				return diff.ErrInvalidData
			}
		case 4:
			valueReader := diff.NewValueReader(payload)
			switch operation {
			case diff.OperationClear:
				value.Slots = nil
			case diff.OperationListAppend:
				itemData := valueReader.Bytes()
				item := &Item{}
				if err := proto.Unmarshal(itemData, item); err != nil {
					return err
				}
				value.Slots = append(value.Slots, item)
			case diff.OperationListInsert:
				index := int(valueReader.Uint32())
				itemData := valueReader.Bytes()
				item := &Item{}
				if err := proto.Unmarshal(itemData, item); err != nil {
					return err
				}
				var zero *Item
				value.Slots = append(value.Slots, zero)
				copy(value.Slots[index+1:], value.Slots[index:len(value.Slots)-1])
				value.Slots[index] = item
			case diff.OperationListSet:
				index := int(valueReader.Uint32())
				itemData := valueReader.Bytes()
				item := &Item{}
				if err := proto.Unmarshal(itemData, item); err != nil {
					return err
				}
				value.Slots[index] = item
			case diff.OperationListDelete:
				index := int(valueReader.Uint32())
				copy(value.Slots[index:], value.Slots[index+1:])
				value.Slots = value.Slots[:len(value.Slots)-1]
			case diff.OperationListMove:
				from := int(valueReader.Uint32())
				to := int(valueReader.Uint32())
				item := value.Slots[from]
				if from < to {
					copy(value.Slots[from:to], value.Slots[from+1:to+1])
				} else {
					copy(value.Slots[to+1:from+1], value.Slots[to:from])
				}
				value.Slots[to] = item
			case diff.OperationListPatch:
				index := int(valueReader.Uint32())
				patch := valueReader.Remaining()
				if err := ApplyItemDiff(value.Slots[index], patch); err != nil {
					return err
				}
			default:
				return diff.ErrInvalidData
			}
			if valueReader.Err() != nil || !valueReader.Done() {
				return diff.ErrInvalidData
			}
		case 5:
			valueReader := diff.NewValueReader(payload)
			switch operation {
			case diff.OperationClear:
				value.Blobs = nil
			case diff.OperationListAppend:
				item := bytes.Clone(valueReader.Bytes())
				value.Blobs = append(value.Blobs, item)
			case diff.OperationListInsert:
				index := int(valueReader.Uint32())
				item := bytes.Clone(valueReader.Bytes())
				var zero []byte
				value.Blobs = append(value.Blobs, zero)
				copy(value.Blobs[index+1:], value.Blobs[index:len(value.Blobs)-1])
				value.Blobs[index] = item
			case diff.OperationListSet:
				index := int(valueReader.Uint32())
				item := bytes.Clone(valueReader.Bytes())
				value.Blobs[index] = item
			case diff.OperationListDelete:
				index := int(valueReader.Uint32())
				copy(value.Blobs[index:], value.Blobs[index+1:])
				value.Blobs = value.Blobs[:len(value.Blobs)-1]
			case diff.OperationListMove:
				from := int(valueReader.Uint32())
				to := int(valueReader.Uint32())
				item := value.Blobs[from]
				if from < to {
					copy(value.Blobs[from:to], value.Blobs[from+1:to+1])
				} else {
					copy(value.Blobs[to+1:from+1], value.Blobs[to:from])
				}
				value.Blobs[to] = item
			default:
				return diff.ErrInvalidData
			}
			if valueReader.Err() != nil || !valueReader.Done() {
				return diff.ErrInvalidData
			}
		case 6:
			if operation == diff.OperationClear {
				if len(payload) != 0 {
					return diff.ErrInvalidData
				}
				value.Counters = nil
				break
			}
			valueReader := diff.NewValueReader(payload)
			key := valueReader.String()
			switch operation {
			case diff.OperationMapPut:
				item := valueReader.Int32()
				if valueReader.Err() != nil || !valueReader.Done() {
					return diff.ErrInvalidData
				}
				if value.Counters == nil {
					value.Counters = make(map[string]int32)
				}
				value.Counters[key] = item
			case diff.OperationMapDelete:
				if valueReader.Err() != nil || !valueReader.Done() {
					return diff.ErrInvalidData
				}
				delete(value.Counters, key)
			default:
				return diff.ErrInvalidData
			}
		}
	}
}

func (s *BagState) ClearDirty() {
	diff.ClearDirty(s.dirty[:])
	s.itemsChanges.ClearDirty()
	s.orderChanges.ClearDirty()
	s.slotsChanges.ClearDirty()
	s.blobsChanges.ClearDirty()
	s.countersChanges.ClearDirty()
}

type Bag2Items struct {
	state *Bag2State
}

type Bag2ItemsValue struct {
	value  *Item
	key    uint64
	parent *Bag2State
}

type bag2ItemsChange struct {
	key       uint64
	operation diff.Operation
	dirty     [1]uint64
}

type bag2ItemsTracker struct {
	indexes map[uint64]int
	changes []bag2ItemsChange
}

func (t *bag2ItemsTracker) Patch(key uint64) (*[1]uint64, bool) {
	if index := t.indexes[key]; index != 0 {
		change := &t.changes[index-1]
		if change.operation != diff.OperationMapPatch {
			return nil, false
		}
		return &change.dirty, false
	}
	if t.indexes == nil {
		t.indexes = make(map[uint64]int)
	}
	first := len(t.changes) == 0
	t.changes = append(t.changes, bag2ItemsChange{key: key, operation: diff.OperationMapPatch})
	t.indexes[key] = len(t.changes)
	return &t.changes[len(t.changes)-1].dirty, first
}

func (t *bag2ItemsTracker) Put(key uint64) bool {
	if index := t.indexes[key]; index != 0 {
		change := &t.changes[index-1]
		change.operation = diff.OperationMapPut
		clear(change.dirty[:])
		return false
	}
	if t.indexes == nil {
		t.indexes = make(map[uint64]int)
	}
	first := len(t.changes) == 0
	t.changes = append(t.changes, bag2ItemsChange{key: key, operation: diff.OperationMapPut})
	t.indexes[key] = len(t.changes)
	return first
}

func (t *bag2ItemsTracker) Delete(key uint64) bool {
	if index := t.indexes[key]; index != 0 {
		change := &t.changes[index-1]
		change.operation = diff.OperationMapDelete
		clear(change.dirty[:])
		return false
	}
	if t.indexes == nil {
		t.indexes = make(map[uint64]int)
	}
	first := len(t.changes) == 0
	t.changes = append(t.changes, bag2ItemsChange{key: key, operation: diff.OperationMapDelete})
	t.indexes[key] = len(t.changes)
	return first
}

func (t *bag2ItemsTracker) Clear() bool {
	clear(t.indexes)
	clear(t.changes)
	t.changes = append(t.changes[:0], bag2ItemsChange{operation: diff.OperationClear})
	return true
}

func (t *bag2ItemsTracker) ClearDirty() {
	clear(t.indexes)
	clear(t.changes)
	t.changes = t.changes[:0]
}

