func (l Bag2Order) Len() int {
	return len(l.state.value.Order)
}

func (l Bag2Order) GetValue(index int) (uint64, bool) {
	if index < 0 || index >= len(l.state.value.Order) {
		var zero uint64
		return zero, false
	}
	return l.state.value.Order[index], true
}

func (l Bag2Order) Clear() {
	if len(l.state.value.Order) == 0 {
		return
	}
	l.state.value.Order = nil
	if l.state.orderChanges.Clear() {
		l.state.markOrderDirty()
	}
}

func (l Bag2Order) Store(index int, value uint64) {
	if l.state.value.Order[index] == value {
		return
	}
	l.state.value.Order[index] = value
	if l.state.orderChanges.Store(uint32(index), value) {
		l.state.markOrderDirty()
	}
}

func (l Bag2Order) Append(value uint64) {
	l.state.value.Order = append(l.state.value.Order, value)
	if l.state.orderChanges.Append(value) {
		l.state.markOrderDirty()
	}
}

func (l Bag2Order) Insert(index int, value uint64) {
	var zero uint64
	l.state.value.Order = append(l.state.value.Order, zero)
	copy(l.state.value.Order[index+1:], l.state.value.Order[index:len(l.state.value.Order)-1])
	l.state.value.Order[index] = value
	if l.state.orderChanges.Insert(uint32(index), value) {
		l.state.markOrderDirty()
	}
}

func (l Bag2Order) Delete(index int) {
	copy(l.state.value.Order[index:], l.state.value.Order[index+1:])
	l.state.value.Order = l.state.value.Order[:len(l.state.value.Order)-1]
	if l.state.orderChanges.Delete(uint32(index)) {
		l.state.markOrderDirty()
	}
}

func (l Bag2Order) Move(from int, to int) {
	if from == to {
		return
	}
	value := l.state.value.Order[from]
	if from < to {
		copy(l.state.value.Order[from:to], l.state.value.Order[from+1:to+1])
	} else {
		copy(l.state.value.Order[to+1:from+1], l.state.value.Order[to:from])
	}
	l.state.value.Order[to] = value
	if l.state.orderChanges.Move(uint32(from), uint32(to)) {
		l.state.markOrderDirty()
	}
}

func (l Bag2Order) Range(yield func(int, uint64) bool) {
	for index, value := range l.state.value.Order {
		if !yield(index, value) {
			return
		}
	}
}

func (s *Bag2State) WriteDiff(writer *diff.Writer) {
	if diff.HasDirty(s.dirty[bag2StateDirtyCapacityWord], bag2StateDirtyCapacityMask) {
		writer.Int32(1, s.value.Capacity)
	}
	if diff.HasDirty(s.dirty[bag2StateDirtyItemsWord], bag2StateDirtyItemsMask) {
		for index := range s.itemsChanges.changes {
			change := &s.itemsChanges.changes[index]
			switch change.operation {
			case diff.OperationClear:
				writer.Clear(2)
			case diff.OperationMapPut:
				data, err := proto.Marshal(s.value.Items[change.key])
				if err != nil {
					panic(err)
				}
				writer.MapPut(2, func(writer *diff.Writer) {
					writer.AppendUint64(change.key)
				}, func(writer *diff.Writer) {
					writer.AppendBytes(data)
				})
			case diff.OperationMapDelete:
				writer.MapDelete(2, func(writer *diff.Writer) {
					writer.AppendUint64(change.key)
				})
			case diff.OperationMapPatch:
				writer.MapPatch(2, func(writer *diff.Writer) {
					writer.AppendUint64(change.key)
				}, func(writer *diff.Writer) {
					if diff.HasDirty(change.dirty[0], 1) {
						writer.Uint64(1, s.value.Items[change.key].Id)
					}
					if diff.HasDirty(change.dirty[0], 2) {
						writer.Int32(2, s.value.Items[change.key].Count)
					}
					if diff.HasDirty(change.dirty[0], 4) {
						writer.Int32(3, s.value.Items[change.key].Level)
					}
				})
			}
		}
	}
	if diff.HasDirty(s.dirty[bag2StateDirtyOrderWord], bag2StateDirtyOrderMask) {
		for _, change := range s.orderChanges.changes {
			switch change.operation {
			case diff.OperationClear:
				writer.Clear(3)
			case diff.OperationListAppend:
				writer.ListAppend(3, func(writer *diff.Writer) {
					writer.AppendUint64(change.value)
				})
			case diff.OperationListInsert:
				writer.ListInsert(3, change.index, func(writer *diff.Writer) {
					writer.AppendUint64(change.value)
				})
			case diff.OperationListSet:
				writer.ListSet(3, change.index, func(writer *diff.Writer) {
					writer.AppendUint64(change.value)
				})
			case diff.OperationListDelete:
				writer.ListDelete(3, change.index)
			case diff.OperationListMove:
				writer.ListMove(3, change.index, change.to)
			}
		}
	}
}

func ApplyBag2Diff(value *Bag2, data []byte) error {
	reader := diff.NewReader(data)
	for {
		fieldNumber, operation, payload, ok, err := reader.Next()
		if err != nil || !ok {
			return err
		}
		switch fieldNumber {
		case 1:
			if operation != diff.OperationSetVarint {
				return diff.ErrInvalidData
			}
			value.Capacity = diff.DecodeInt32(payload)
		case 2:
			if operation == diff.OperationClear {
				if len(payload) != 0 {
					return diff.ErrInvalidData
				}
				value.Items = nil
				break
			}
			valueReader := diff.NewValueReader(payload)
			key := valueReader.Uint64()
			switch operation {
			case diff.OperationMapPut:
				itemData := valueReader.Bytes()
				item := &Item{}
				if err := proto.Unmarshal(itemData, item); err != nil {
					return err
				}
				if valueReader.Err() != nil || !valueReader.Done() {
					return diff.ErrInvalidData
				}
				if value.Items == nil {
					value.Items = make(map[uint64]*Item)
				}
				value.Items[key] = item
			case diff.OperationMapDelete:
				if valueReader.Err() != nil || !valueReader.Done() {
					return diff.ErrInvalidData
				}
				delete(value.Items, key)
			case diff.OperationMapPatch:
				patch := valueReader.Remaining()
				if valueReader.Err() != nil {
					return diff.ErrInvalidData
				}
				item := value.Items[key]
				if item == nil {
					item = &Item{}
					if value.Items == nil {
						value.Items = make(map[uint64]*Item)
					}
					value.Items[key] = item
				}
				if err := ApplyItemDiff(item, patch); err != nil {
					return err
				}
			default:
				return diff.ErrInvalidData
			}
		case 3:
			valueReader := diff.NewValueReader(payload)
			switch operation {
			case diff.OperationClear:
				value.Order = nil
			case diff.OperationListAppend:
				item := valueReader.Uint64()
				value.Order = append(value.Order, item)
			case diff.OperationListInsert:
				index := int(valueReader.Uint32())
				item := valueReader.Uint64()
				var zero uint64
				value.Order = append(value.Order, zero)
				copy(value.Order[index+1:], value.Order[index:len(value.Order)-1])
				value.Order[index] = item
			case diff.OperationListSet:
				index := int(valueReader.Uint32())
				item := valueReader.Uint64()
				value.Order[index] = item
			case diff.OperationListDelete:
				index := int(valueReader.Uint32())
				copy(value.Order[index:], value.Order[index+1:])
				value.Order = value.Order[:len(value.Order)-1]
			case diff.OperationListMove:
				from := int(valueReader.Uint32())
				to := int(valueReader.Uint32())
				item := value.Order[from]
				if from < to {
					copy(value.Order[from:to], value.Order[from+1:to+1])
				} else {
					copy(value.Order[to+1:from+1], value.Order[to:from])
				}
				value.Order[to] = item
			default:
				return diff.ErrInvalidData
			}
			if valueReader.Err() != nil || !valueReader.Done() {
				return diff.ErrInvalidData
			}
		}
	}
}

func (s *Bag2State) ClearDirty() {
	diff.ClearDirty(s.dirty[:])
	s.itemsChanges.ClearDirty()
	s.orderChanges.ClearDirty()
}

